catalog_script_client.script:
function onSubmit() {
    var req_item_id = getURLParam('req_item_id');
    if (req_item_id) {
        var qa1 = g_form.getValue('office_supply_select');
        var qa2 = g_form.getValue('quantity');
        var qa3 = g_form.getValue('description');

        var ga = new GlideAjax('SaveRequestItem');
        ga.addParam('sysparm_name', 'save');
        ga.addParam('req_item_id', req_item_id);
        ga.addParam('qa1', qa1);
        ga.addParam('qa2', qa2);
        ga.addParam('qa3', qa3);
        ga.getXMLAnswer(parseAnswer);
        return false;
    }
}

function parseAnswer(response) {
    var data = JSON.parse(response);
    if (data['status'] == 'ok') {
        top.window.onbeforeunload = null;
        top.window.onunload = null;
        top.window.location = 'https://dev322415.service-now.com/sp?id=ticket&table=sc_req_item&sys_id=' + data['req_item_id'] + '&view=sp';
    }
}

function getURLParam(name) {
    name = name.replace(/[\[]/, "\\\[").replace(/[\]]/, "\\\]");
    var regexS = "[\\?&]" + name + "=([^&#]*)";
    var regex = new RegExp(regexS);
    var results = regex.exec(top.location);
    if (results == null) {
        return "";
    } else {
        return unescape(results[1]);
    }
}
